class OperandBuffer:
    """A DLPack producer over memory the caller did not supply (a workspace carve): the shim's stand-in for the
    extension's ``OperandBuffer``.  Compact row-major; ``strides`` NULL as DLPack allows."""

    def __init__(self, ptr, shape, dtype_code, dtype_bits, device_id):
        self.ptr, self.shape, self.code, self.bits, self.device_id = int(ptr), [int(s) for s in shape], int(dtype_code), int(dtype_bits), int(device_id)
        n = len(self.shape)
        self._shape = (ctypes.c_int64 * max(n, 1))(*self.shape)
        self._mt = _DLManagedTensor()
        t = self._mt.dl_tensor
        t.data = ctypes.c_void_p(self.ptr)
        t.device = _DLDevice(_KDL_CUDA, self.device_id)
        t.ndim = n
        t.dtype = _DLDataType(self.code, self.bits, 1)
        t.shape = ctypes.cast(self._shape, ctypes.POINTER(ctypes.c_int64))
        t.strides = None
        t.byte_offset = 0
        self._mt.manager_ctx = None
        self._mt.deleter = _noop_deleter

    def __dlpack_device__(self):
        return (_KDL_CUDA, self.device_id)

    def __dlpack__(self, *, stream=None, **_kwargs):
        _RETAINED.append(self)
        return _PyCapsule_New(ctypes.addressof(self._mt), b"dltensor", None)

    @property
    def nbytes(self):
        n = self.bits // 8
        for s in self.shape:
            n *= s
        return n


def make_operand_buffer(ptr, shape, dtype_code, dtype_bits, device_id):
    """A DLPack producer over memory the caller did not supply -- a workspace carve."""
    return OperandBuffer(ptr, shape, dtype_code, dtype_bits, device_id)


class WorkspaceCarve:
    """A workspace carve compiled once, at build.  Regions are ``(offset, dtype_code, dtype_bits, shape)``; ``carve`` hands back
    every region over the base pointer handed per execute, bounds-checked against ``nbytes`` when it is known."""

    def __init__(self, owner, spec):
        self.owner = str(owner)
        self.spec = [(int(o), int(c), int(b), [int(x) for x in s]) for (o, c, b, s) in spec]

    def __len__(self):
        return len(self.spec)

    def carve(self, base, nbytes, device_id):
        out = []
        for off, code, bits, shape in self.spec:
            n = bits // 8
            for s in shape:
                n *= s
            if nbytes is not None and off + n > int(nbytes):
                raise ValueError(f"{self.owner}: workspace region at {off} (+{n} B) exceeds the {int(nbytes)}-byte buffer")
            out.append(OperandBuffer(int(base) + off, shape, code, bits, device_id))
        return out
